  voice_description: string,
  /** @default null */
  text?: string | null,
  /** @default null */
  output_directory?: string | null,
}): Promise<{
  result: Array<{
        type: "resource",
        resource: {
            /** @format uri @minLength 1 */
            uri: string,
            /** @default null */
            mimeType?: string | null,
            /** @default null */
            _meta?: {} | null,
            text: string,
          } | {
            /** @format uri @minLength 1 */
            uri: string,
            /** @default null */
            mimeType?: string | null,
            /** @default null */
            _meta?: {} | null,
            blob: string,
          },
        /** @default null */
        annotations?: {
            /** @default null */
            audience?: Array<"user" | "assistant"> | null,
            /** @default null */
            priority?: number | null,
          } | null,
